<?php if(supervisor_team(database(),(int)current_user()['id'])): ?><nav class="supervision-context"><a href="supervision.php"><?= stock_icon('users') ?>Mi equipo</a><strong><?= stock_icon('branch') ?>Mi sucursal</strong></nav><?php endif; ?>
