<h2>Invitación a <?= escape($invite['name']) ?></h2><p>Acceso como <?= $invite['role']==='manager'?'encargado':'operador' ?>. <?= $invite['access_seconds']?'Durante '.((int)$invite['access_seconds']/3600).' horas desde el ingreso.':'Sin vencimiento de acceso.' ?> Usás tu misma cuenta.</p>
<button type="button" class="library-primary" id="teamAccept" data-token="<?= escape($token) ?>" data-direct="<?= $invite['recipient_id']===null?'1':'0' ?>" data-security="<?= team_security(database(),(int)$invite['branch_id'])['enabled'] ?>"><?= $invite['recipient_id']===null?'Ingresando al equipo…':'Aceptar invitación' ?></button>
<?php else: ?><p>La invitación venció o ya fue utilizada. Pedí una nueva.</p><?php unset($_SESSION['branch_team_invitation']);endif; ?>
</section><?php endif; ?>

